#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<long long> a(n), b(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n; i++) cin >> b[i];
    sort(a.rbegin(), a.rend());
    long long ans = 1;
    for (int i = 0; i < n; i++) {
        long long fit = 0;
        for (int j = 0; j < n; j++) {
            if (b[j] >= a[i]) fit++;
        }
        if (fit - i <= 0) { ans = 0; break; }
        ans *= (fit - i);
    }
    cout << ans << '\n';
    return 0;
}

