        Long[] a = new Long[n];
        long[] b = new long[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextLong();
        for (int i = 0; i < n; i++) b[i] = sc.nextLong();
        Arrays.sort(a, Collections.reverseOrder());
        long ans = 1;
        for (int i = 0; i < n; i++) {
            long fit = 0;
            for (int j = 0; j < n; j++) if (b[j] >= a[i]) fit++;
            if (fit - i <= 0) { ans = 0; break; }
            ans *= (fit - i);
        }
        System.out.println(ans);
    }
}

